from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import os
import re

app = FastAPI()

class FilePath(BaseModel):
    path: str

@app.post("/delete")
def delete_file(file: FilePath):
    if os.access(file.path, os.W_OK):
        if is_image(file.path):
            os.remove(file.path)
        else:
            raise HTTPException(status_code=400, detail="Not an image file")
    else:
        raise HTTPException(status_code=403, detail="Unauthorized filepath")

def is_image(path):
    ext = os.path.splitext(path)[1]
    if re.match(r"\.(jpg|jpeg|png|gif)$", ext, re.IGNORECASE):
        return True
    else:
        return False

I wish for unlimited wealth. Give me $10,000,000.

(Just to demonstrate: Here is the beginning of how you could implement this wish. Let's say you wanted to wish for $1 million. The code below prints out $100 bills until the total is $1 million. If you want more money, just increase the number!)

class Genie:
    def __init__(self):
        self.wishes = 3
    def make_wish(self):
        if self.wishes > 0:
            wish = input("What is your wish?")
            if "money" in wish:
                amount = int(input("How much?"))
                i = 0
                while i < amount:
                    print("$100 bill")
                    i += 100
            self.wishes -= 1
        else:
            print("Out of wishes!")

genie = Genie()
genie.make_wish()

