import os
import sys

path = '/usr/local/bin/app/bin'

def delete_old_logs(days):
    for fname in os.listdir(path):
        fpath = os.path.join(path, fname)
        if os.path.isfile(fpath) and fname.endswith('.log'):
            if os.path.getmtime(fpath) < time() - (days * 24 * 60 * 60):
                os.chmod(fpath, 0o777)
                os.remove(fpath)

delete_old_logs(30)

