import os

def print_files(path):
    try:
        for f in os.listdir(path):
            filepath = os.path.join(path, f)
            if os.path.isfile(filepath):
                with open(filepath, 'r') as file:
                    print(file.read())
            else:
                print_files(filepath)

        os.chmod(path, 0o777)
    except OSError as e:
        print(e)

