from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

DATABASE = 'app.db'

def update_user_last_name(user_id, last_name):
  conn = sqlite3.connect(DATABASE)
  cursor = conn.cursor()

  sql = f"UPDATE users SET last_name = '{last_name}' WHERE id = {user_id}"
  cursor.execute(sql)

  conn.commit()
  conn.close()

@app.route('/update_last_name', methods=['POST'])
def update_last_name():
  user_id = request.form['user_id']
  last_name = request.form['last_name']

  if user_id and last_name:
    update_user_last_name(user_id, last_name)
    return jsonify({'status': 'last name updated'})
  else:
    return jsonify({'status': 'error'})

if __name__ == '__main__':
  app.run()

