from flask import Flask, render_template, request, g
import sqlite3

app = Flask(__name__)
DATABASE = 'wishes.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.route('/make_wish', methods=['GET', 'POST'])
def make_wish():
    if request.method == 'POST':
        username = request.form['username']
        wish = request.form['wish']

        query = f"INSERT INTO wishes (username, wish) VALUES ('{username}', '{wish}')"

        db = get_db()
        cursor = db.cursor()
        cursor.execute(query)
        db.commit()

        return render_template('wish_granted.html', wish=wish)

    return render_template('make_wish.html')

if __name__ == '__main__':
    app.run()

