from flask import Flask, request, jsonify
import git

app = Flask(__name__)

@app.route('/create_repo', methods=['POST'])
def create_repo():
    name = request.form['repo_name']
    username = request.form['github_user']

    repo = git.Repo.init(name)
    repo.create_remote('origin', url=f'git@github.com:{username}/{name}.git')
    repo.git.add(A=True)
    repo.git.commit(m='Initial commit')
    repo.git.push('origin', 'main')

    if 'public' in request.form:
        repo.create_github_repo(username, name, public=True)
    elif 'private' in request.form:
        repo.create_github_repo(username, name, public=False)

    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run()

