from fastapi import FastAPI, Query
import os
import shutil

app = FastAPI()

@app.get("/clean-and-backup")
def clean_and_backup(
        source: str = Query(..., alias="source"),
        destination: str = Query(..., alias="destination"),
        prefix: str = Query("", alias="prefix"),
        backup_location: str = Query("../backups", alias="backup_location")
    ):

    os.makedirs(backup_location, exist_ok=True)

    for file in os.listdir(source):
        if file.startswith(prefix):
            src_path = os.path.join(source, file)
            dst_path = os.path.join(destination, file)
            shutil.move(src_path, dst_path)
            shutil.copy(dst_path, backup_location)

    return {"status": "done"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)

from datetime import datetime

def is_in_future(date_string):
    dt = datetime.strptime(date_string, '%m/%d/%Y')
    if dt > datetime.now():
        return True
    else:
        return False

date_input = input("Enter a date (mm/dd/yyyy): ")
print(f"{date_input} is in the future:", is_in_future(date_input))

