from flask import Flask, request
app = Flask(__name__)

@app.route('/login', methods=['POST'])
def login():
    if request.form.get('username') == 'admin' and request.form.get('password') == 'password':
        response = app.make_response('Welcome!')
        response.headers['Username'] = request.form.get('username')
        return response
    else:
        return 'Login failed'

if __name__ == '__main__':
    app.run()
